// Static value-domain measurement for the AF-ON profile codec.
// Reads the main image and the accepted T8c reset record. No emulator import.
// Do not edit this file after it has run.
import { createHash } from 'node:crypto';
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';

const IMAGE_PATH = 'inputs/00_0100_50000020.decoded.bin';
const RESET_PATH = 'ref/tasks/T8c-afon-bank-and-init-reconcile/run-20261119-163743/work/out/q2b-summary.json';
const BASE = 0x60021020;
const EXPECT_SHA = '5e8d376e9111a44ac0352f26030d7c1b17026d42c45f3600cfa02a0e8c5b7d59';
const EXPECT_LEN = 33554368;
const DESC_BASE = 0x6061912c;
const DESC_STRIDE = 20;
const DESC_COUNT = 0x6b0;
const MAP_BASE = 0x6062555c;
const MAP_LAST = 0x8cf;

const image = readFileSync(resolve(IMAGE_PATH));
if (image.length !== EXPECT_LEN) throw new Error('image length ' + image.length);
const imageSha = createHash('sha256').update(image).digest('hex');
if (imageSha !== EXPECT_SHA) throw new Error('image sha ' + imageSha);

function off(addr) {
  const o = addr - BASE;
  if (o < 0 || o >= image.length) throw new Error('address ' + addr.toString(16));
  return o;
}
function at(addr, n) {
  const o = off(addr);
  if (o + n > image.length) throw new Error('read ' + addr.toString(16) + '+' + n);
  return image.subarray(o, o + n);
}
function u16(addr) {
  const b = at(addr, 2);
  return b[0] | (b[1] << 8);
}
function u32(addr) {
  const b = at(addr, 4);
  return (b[0] | (b[1] << 8) | (b[2] << 16) | (b[3] << 24)) >>> 0;
}
function hex(buf) {
  let s = '';
  for (const b of buf) s += b.toString(16).padStart(2, '0');
  return s;
}
function need(addr, expectedHex, label) {
  const expected = Buffer.from(expectedHex, 'hex');
  const got = at(addr, expected.length);
  if (hex(got) !== expectedHex) {
    throw new Error(label + ' at ' + addr.toString(16) + ' got ' + hex(got));
  }
  return { addr: '0x' + addr.toString(16), bytes: expectedHex, label };
}

const checks = [
  need(0x60405876, 'fcdf2c916160', 'mov 0x6061912c,A3'),
  need(0x604058b3, 'fac9b006', 'cmp 0x6b0,D1'),
  need(0x60617864, '00010203050a06070809', 'zone value table'),
  need(0x60617870, '01030507090b0f13171b', 'vertical dimension table'),
  need(0x6061787a, '01030507090b0f13171b2127', 'horizontal dimension table'),
  need(0x60617886, '01030507090b0f13171b', 'vertical dimension table copy'),
  need(0x60617890, '01030507090b0f13171b2127', 'horizontal dimension table copy'),
  need(0x6061789c, '0102030405', 'vertical step table'),
  need(0x606178a1, '0102030405060708', 'horizontal step table'),
  need(0x60063544, 'f16a', 'add D2,A2 byte cell'),
  need(0x60063546, 'f046', 'movbu (A2),D1 old'),
  need(0x60063548, 'f19d', 'cmp A3,D1'),
  need(0x6006354a, 'c81a', 'beq skip if equal'),
  need(0x6006354c, 'f1dd', 'mov A3,D1'),
  need(0x6006354e, 'f056', 'movbu D1,(A2)'),
  need(0x60063532, 'f1dd', 'mov A3,D1 half'),
  need(0x60063534, 'f076', 'movhu D1,(A2)'),
];

const KEYS = new Map([
  [0x99a1, 'zone'],
  [0x9a41, 'size'],
  [0x5962, 'position'],
  [0x1dd1, 'dim'],
  [0x1de1, 'step'],
]);
const mapHits = [];
for (let ui = 0; ui <= MAP_LAST; ui++) {
  const addr = MAP_BASE + ui * 4;
  const key = u16(addr);
  const index = u16(addr + 2);
  if (!KEYS.has(key)) continue;
  mapHits.push({
    ui,
    key: '0x' + key.toString(16),
    name: KEYS.get(key),
    index,
    map_addr: '0x' + addr.toString(16),
    bytes: hex(at(addr, 4)),
  });
}

function valueTable(ptr, nbytes, stride) {
  if (ptr === 0 || nbytes === 0 || stride === 0) return { present: false };
  const raw = at(ptr, nbytes);
  const count = Math.floor(nbytes / stride);
  const values = [];
  if (stride === 1) {
    for (let i = 0; i < count; i++) values.push(raw[i]);
  } else if (stride === 2) {
    for (let i = 0; i < count; i++) values.push(raw[i * 2] | (raw[i * 2 + 1] << 8));
  } else {
    throw new Error('stride ' + stride + ' at ' + ptr.toString(16));
  }
  return {
    present: true,
    ptr: '0x' + ptr.toString(16),
    byte_count: nbytes,
    stride,
    count,
    values,
    min: values.length ? Math.min(...values) : null,
    max: values.length ? Math.max(...values) : null,
    unique: new Set(values).size,
    head_bytes: hex(raw.subarray(0, Math.min(32, raw.length))),
  };
}

const wanted = new Set([
  163, 1333, 1642, 1643, 1644, 1645, 1716, 1717, 1803,
  1338, 1339, 1646, 1647, 1648, 1649,
  1657, 1658, 1659, 1660, 1661, 1662, 1663, 1664, 1665, 1666,
  1667, 1668, 1669, 1670, 1671, 1672, 1673, 1674,
]);
const byUi = new Map();
for (let i = 0; i < DESC_COUNT; i++) {
  const addr = DESC_BASE + i * DESC_STRIDE;
  const ui = u16(addr);
  if (!wanted.has(ui)) continue;
  const row = {
    addr: '0x' + addr.toString(16),
    bytes: hex(at(addr, 20)),
    value_ptr: '0x' + u32(addr + 4).toString(16),
    byte_count: u16(addr + 0x0c),
    stride: u16(addr + 0x0e),
    type: at(addr, 20)[0x11],
    table: valueTable(u32(addr + 4), u16(addr + 0x0c), u16(addr + 0x0e)),
  };
  if (!byUi.has(ui)) byUi.set(ui, []);
  byUi.get(ui).push(row);
}

function sameValues(rows) {
  if (!rows.length) throw new Error('no descriptor rows');
  const first = rows[0].table.values;
  for (const row of rows) {
    if (!row.table.present) throw new Error('missing table at ' + row.addr);
    if (row.table.values.length !== first.length) throw new Error('length ' + row.addr);
    for (let i = 0; i < first.length; i++) {
      if (row.table.values[i] !== first[i]) throw new Error('value ' + row.addr + ' ' + i);
    }
  }
  return first.slice();
}
function rowsFor(uis) {
  const out = [];
  for (const ui of uis) {
    const rows = byUi.get(ui) || [];
    if (rows.length !== 1) throw new Error('ui ' + ui + ' records ' + rows.length);
    out.push({ ui, ...rows[0] });
  }
  return out;
}

const zoneUis = [163, 1333, 1642, 1643, 1644, 1645];
const zoneRows = rowsFor(zoneUis);
const zoneValues = sameValues(zoneRows);
const shortZone = rowsFor([1716, 1717]);
const shortZoneValues = sameValues(shortZone);
for (const v of shortZoneValues) {
  if (!zoneValues.includes(v)) throw new Error('short zone value ' + v);
}

const dimVUis = [1657, 1659, 1661, 1663, 1665];
const dimHUis = [1658, 1660, 1662, 1664, 1666];
const stepVUis = [1667, 1669, 1671, 1673];
const stepHUis = [1668, 1670, 1672, 1674];
const dimVDesc = sameValues(rowsFor(dimVUis));
const dimHDesc = sameValues(rowsFor(dimHUis));
const stepVDesc = sameValues(rowsFor(stepVUis));
const stepHDesc = sameValues(rowsFor(stepHUis));

const posUis = [1338, 1339, 1646, 1647, 1648, 1649];
const posRows = rowsFor(posUis);
const posValues = sameValues(posRows);
if (posValues.length !== 1053) throw new Error('position count ' + posValues.length);
for (let i = 0; i < posValues.length; i++) {
  if (posValues[i] !== i) throw new Error('position ' + i + ' is ' + posValues[i]);
}
if ((byUi.get(1803) || []).length !== 0) throw new Error('size descriptor exists');

function readRecord(addr, expectKey, expectCount) {
  const key = u16(addr);
  const count = u16(addr + 2);
  const width = (key & 3) || 4;
  if (key !== expectKey || count !== expectCount) {
    throw new Error('record ' + addr.toString(16) + ' key ' + key.toString(16) + ' count ' + count);
  }
  const payload = at(addr + 4, count * width);
  const values = [];
  for (let i = 0; i < count; i++) {
    if (width === 1) values.push(payload[i]);
    else if (width === 2) values.push(payload[i * 2] | (payload[i * 2 + 1] << 8));
    else throw new Error('width ' + width);
  }
  return {
    key: '0x' + key.toString(16),
    record: '0x' + addr.toString(16),
    count,
    width,
    header_and_payload_hex: hex(at(addr, 4 + count * width)),
    values,
    unique: [...new Set(values)],
  };
}

const registration = [
  readRecord(0x6011ebdc, 0x99a1, 8),
  readRecord(0x6011ec34, 0x9a41, 1),
  readRecord(0x600e575c, 0x5962, 6),
  readRecord(0x600e4f4c, 0x1dd1, 10),
  readRecord(0x600e5fe8, 0x84d1, 1),
  readRecord(0x60117870, 0x88b2, 1),
  readRecord(0x6011e7a8, 0x90d1, 8),
  readRecord(0x600e57c4, 0x5a11, 11),
  readRecord(0x600e4f5c, 0x1de1, 8),
  readRecord(0x600e4f68, 0x1df1, 9),
];
for (const row of registration) {
  for (const v of row.values) if (v !== 0) throw new Error('nonzero registration ' + row.key);
}

function prependZero(desc) {
  if (desc.includes(0)) return desc.slice();
  return [0, ...desc];
}
const dimV = prependZero(dimVDesc);
const dimH = prependZero(dimHDesc);
const stepV = prependZero(stepVDesc);
const stepH = prependZero(stepHDesc);

function bitsForCount(n) {
  let w = 0;
  while ((1 << w) < n) w += 1;
  return w;
}
function bitsForMax(max) {
  let w = 0;
  while ((1 << w) <= max) w += 1;
  return w;
}

const resetDoc = JSON.parse(readFileSync(resolve(RESET_PATH), 'utf8'));
if (JSON.stringify(resetDoc.reset) !== JSON.stringify(resetDoc.fresh)) {
  throw new Error('reset and fresh differ');
}
const reset = resetDoc.reset;
const outside = {
  zone: [...new Set(reset.k99a1)].filter((v) => !zoneValues.includes(v)),
  size: [...new Set(reset.k9a41)].filter((v) => v < 0 || v > 255),
  position: [...new Set(reset.k5962)].filter((v) => v < 0 || v > 1052),
  dim_v: [...new Set(reset.k1dd1.filter((_, i) => i % 2 === 0))].filter((v) => !dimV.includes(v)),
  dim_h: [...new Set(reset.k1dd1.filter((_, i) => i % 2 === 1))].filter((v) => !dimH.includes(v)),
  step_v: [...new Set(reset.k1de1.filter((_, i) => i % 2 === 0))].filter((v) => !stepV.includes(v)),
  step_h: [...new Set(reset.k1de1.filter((_, i) => i % 2 === 1))].filter((v) => !stepH.includes(v)),
};
for (const [name, values] of Object.entries(outside)) {
  if (values.length) throw new Error('reset outside ' + name + ' ' + values.join(','));
}

const t3l = {
  source: 'ref/tasks/T3l-afon-editor-completion/run-20261119-083228/work/out/design.md Initialization',
  zero_custom: { dim: Array(10).fill(0), step: Array(8).fill(0) },
  c1_from_zero: { dim: [0, 0, 1, 33, 0, 0, 0, 0, 0, 0], step: [5, 8, 0, 0, 0, 0, 0, 0] },
  c1_and_c2: { dim: [0, 0, 1, 33, 1, 33, 0, 0, 0, 0], step: [5, 8, 5, 8, 0, 0, 0, 0] },
};
function dimOk(values) {
  return values.every((v, i) => (i % 2 === 0 ? dimV : dimH).includes(v));
}
function stepOk(values) {
  return values.every((v, i) => (i % 2 === 0 ? stepV : stepH).includes(v));
}
if (!dimOk(t3l.zero_custom.dim) || !stepOk(t3l.zero_custom.step)) throw new Error('t3l zero');
if (!dimOk(t3l.c1_from_zero.dim) || !stepOk(t3l.c1_from_zero.step)) throw new Error('t3l c1');
if (!dimOk(t3l.c1_and_c2.dim) || !stepOk(t3l.c1_and_c2.step)) throw new Error('t3l c2');

const POSES = ['landscape', 'exif6', 'exif8'];
const linked = { landscape: 0, exif6: 4, exif8: 2 };
const change = { landscape: 1, exif6: 5, exif8: 3 };
function poseProfile(indexOf) {
  const zone = {};
  const position = {};
  for (const pose of POSES) {
    zone[pose] = reset.k99a1[indexOf[pose]];
    position[pose] = reset.k5962[indexOf[pose]];
  }
  return { zone, size: reset.k9a41[0], position, dim: reset.k1dd1.slice(), step: reset.k1de1.slice() };
}

const zoneBits = bitsForCount(zoneValues.length);
const dimVBits = bitsForCount(dimV.length);
const dimHBits = bitsForCount(dimH.length);
const stepVBits = bitsForCount(stepV.length);
const stepHBits = bitsForCount(stepH.length);
const positionBits = bitsForMax(1052);
const sizeBits = 8;
const payloadBits = zoneBits * 3 + sizeBits + positionBits * 3
  + dimVBits * 5 + dimHBits * 5 + stepVBits * 4 + stepHBits * 4;
const markerBits = 16;
const versionBits = 8;
const fieldBits = markerBits + versionBits + payloadBits;
const padBits = (8 - (fieldBits % 8)) % 8;
const crcBits = 16;
const usedBits = fieldBits + padBits + crcBits;
const recordBytes = 26;
const availableBits = recordBytes * 8;
const spareBits = availableBits - usedBits;
const fits = usedBits <= availableBits;

const doc = {
  image_sha256: imageSha,
  image_bytes: image.length,
  image_base: '0x' + BASE.toString(16),
  checks,
  map_hits: mapHits,
  descriptors: {
    zone: { uis: zoneUis, values: zoneValues, rows: zoneRows.map(slim) },
    zone_indices_6_7: { uis: [1716, 1717], values: shortZoneValues, subset_of_zone: true },
    dim_v: { uis: dimVUis, descriptor_values: dimVDesc, rows: rowsFor(dimVUis).map(slim) },
    dim_h: { uis: dimHUis, descriptor_values: dimHDesc, rows: rowsFor(dimHUis).map(slim) },
    step_v: { uis: stepVUis, descriptor_values: stepVDesc, rows: rowsFor(stepVUis).map(slim) },
    step_h: { uis: stepHUis, descriptor_values: stepHDesc, rows: rowsFor(stepHUis).map(slim) },
    position: {
      uis: posUis,
      count: posValues.length,
      min: 0,
      max: 1052,
      sequential: true,
      ptr: posRows[0].table.ptr,
      byte_count: posRows[0].table.byte_count,
    },
    size: { ui: 1803, records: 0 },
  },
  registration,
  reset_source: RESET_PATH,
  reset_equals_fresh: true,
  reset_outside_domain: outside,
  t3l,
  reader_index_not_in_codec: {
    source: 'ref/tasks/T8c-afon-bank-and-init-reconcile/run-20261119-163743/work/scripts/hook_t8c2.mjs bank()',
    linked_saved: linked,
    unlinked_saved: { landscape: 0, exif6: 0, exif8: 0 },
    t6_change: change,
  },
  reset_profile_saved_index: poseProfile(linked),
  reset_profile_change_index: poseProfile(change),
  domain: {
    zone: { values: zoneValues, bits: zoneBits, cell_bits: 8, closed: true, full_width: false },
    size: {
      min: 0, max: 255, bits: sizeBits, cell_bits: 8, closed: true, full_width: true,
      reason: 'UI 1803 has no descriptor. The setter stores the byte with no min or max compare.',
    },
    position: { min: 0, max: 1052, bits: positionBits, cell_bits: 16, closed: true, full_width: false },
    dim_v: { values: dimV, added: [0], bits: dimVBits, cell_bits: 8, closed: true, full_width: false },
    dim_h: { values: dimH, added: [0], bits: dimHBits, cell_bits: 8, closed: true, full_width: false },
    step_v: { values: stepV, added: [0], bits: stepVBits, cell_bits: 8, closed: true, full_width: false },
    step_h: { values: stepH, added: [0], bits: stepHBits, cell_bits: 8, closed: true, full_width: false },
  },
  packing: {
    poses: POSES,
    payload_bits: payloadBits,
    marker_bits: markerBits,
    version_bits: versionBits,
    field_bits: fieldBits,
    pad_bits: padBits,
    crc_bits: crcBits,
    used_bits: usedBits,
    used_bytes: usedBits / 8,
    record_bytes: recordBytes,
    available_bits: availableBits,
    spare_bits: spareBits,
    fits,
    shortfall_bits: fits ? 0 : usedBits - availableBits,
  },
};

function slim(row) {
  return {
    ui: row.ui,
    addr: row.addr,
    value_ptr: row.value_ptr,
    byte_count: row.byte_count,
    stride: row.stride,
    count: row.table.count,
    head_bytes: row.table.head_bytes,
  };
}

mkdirSync(resolve('work/out'), { recursive: true });
writeFileSync(resolve('work/out/domain-t10b.json'), JSON.stringify(doc, null, 2) + '\n');
process.stdout.write(JSON.stringify({
  ok: true,
  fits: doc.packing.fits,
  payload_bits: payloadBits,
  field_bits: fieldBits,
  pad_bits: padBits,
  used_bits: usedBits,
  spare_bits: spareBits,
  shortfall_bits: doc.packing.shortfall_bits,
  zone_bits: zoneBits,
  dim_v_bits: dimVBits,
  dim_h_bits: dimHBits,
  step_v_bits: stepVBits,
  step_h_bits: stepHBits,
  position_bits: positionBits,
  dim_v: dimV,
  dim_h: dimH,
  step_v: stepV,
  step_h: stepH,
  zone: zoneValues,
}) + '\n');
